query ProbeSearchPaged($text: String!, $size: Int!, $index: Int!) {
  search(queryString: $text, entityNames: ["disease"], page: {index: $index, size: $size}) {
    total
    hits {
      id
      entity
      name
      category
      object { ... on Disease { synonyms { relation terms } } }
    }
  }
}
